import java.util.Scanner;

public class Main {
    public static int gcd(int x, int y) {
        int gcd;
        if (x > y)
            gcd = x;
        else
            gcd = y;

        while (true) {
            if (x % gcd == 0 && y % gcd == 0)
                break;
            gcd--;
        }
        return gcd;
    }

    public static void diff(double x, double y, double a, double b, double[] num, double[] den) {
        num[0] = x * b - y * a;
        num[0] = Math.abs(num[0]);
        den[0] = y * b;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        double x, y, n;
        x = sc.nextDouble();
        y = sc.nextDouble();
        n = sc.nextDouble();

        double min = 1000000;
        int mina = 0, minb = 0;

        if (n > y) {
            int gc = gcd((int) x, (int) y);
            if (gc != 1) {
                x = x / gc;
                y = y / gc;
            }
            System.out.println((int) x + "/" + (int) y);
            sc.close();
            return;
        }

        for (double b = n; b >= 1; b--) {
            double a = (x * b) / y;
            if (Math.floor(a) == a) {
                mina = (int) a;
                minb = (int) b;
                break;
            } else {
                double[] tempa = new double[1];
                double[] tempb = new double[1];
                diff(x, y, Math.floor(a), b, tempa, tempb);
                double temp = tempa[0] / tempb[0];

                if (temp < min) {
                    mina = (int) Math.floor(a);
                    minb = (int) b;
                    min = temp;
                } else if (temp == min) {
                    if (Math.floor(a) < mina) {
                        mina = (int) Math.floor(a);
                        minb = (int) b;
                    }
                }

                diff(x, y, Math.ceil(a), b, tempa, tempb);
                temp = tempa[0] / tempb[0];

                if (temp < min) {
                    mina = (int) Math.ceil(a);
                    minb = (int) b;
                    min = temp;
                } else if (temp == min) {
                    if (Math.ceil(a) < mina) {
                        mina = (int) Math.ceil(a);
                        minb = (int) b;
                    }
                }
            }
        }

        int gc = gcd(mina, minb);
        if (gc != 1) {
            mina = mina / gc;
            minb = minb / gc;
        }

        System.out.println(mina + "/" + minb);
        sc.close();
    }
}
